 "content": "def transform(grid):
    """For each nonzero input cell, stamp its color at zero positions of the input pattern."""
    n = len(grid)
    m = len(grid[0]) if n else 0
    out = [[0 for _ in range(n * m)] for _ in range(n * m)]
    for br in range(n):
        for bc in range(m):
            color = grid[br][bc]
            if color:
                for r in range(n):
                    for c in range(m):
                        if grid[r][c] == 0:
                            out[br * n + r][bc * m + c] = color
    return out

